#include "virtual_broadcast/broadcaster/data_broadcast.hpp"
#include "virtual_broadcast/common/ts.hpp"
#include <algorithm>
#include <cctype>
#include <fstream>
#include <map>
#include <set>
#include <stdexcept>

namespace vb { namespace {
void U16(std::vector<std::uint8_t>&b,std::uint16_t v){b.push_back(v>>8);b.push_back(v);}
void U32(std::vector<std::uint8_t>&b,std::uint32_t v){b.push_back(v>>24);b.push_back(v>>16);b.push_back(v>>8);b.push_back(v);}
void Crc(std::vector<std::uint8_t>&b){const auto c=MpegCrc32(b);U32(b,c);}
std::uint32_t Hash(std::span<const std::uint8_t>s){std::uint32_t h=2166136261u;for(auto c:s){h^=c;h*=16777619u;}return h;}
std::uint32_t Hash(std::string_view s){return Hash(std::span(reinterpret_cast<const std::uint8_t*>(s.data()),s.size()));}
std::vector<std::uint8_t> Read(const std::filesystem::path&p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("cannot read data broadcast resource");return {std::istreambuf_iterator<char>(f),{}};}
std::string Lower(std::string s){std::transform(s.begin(),s.end(),s.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));});return s;}
std::string Mime(const std::filesystem::path&p){const auto e=Lower(p.extension().string());if(e==".bml")return "text/X-arib-bml; charset=UTF-8";if(e==".css")return "text/css; charset=UTF-8";if(e==".js")return "application/X-arib-ecmascript; charset=UTF-8";if(e==".png")return "image/png";if(e==".jpg"||e==".jpeg")return "image/jpeg";throw std::runtime_error("unsupported data broadcast resource: "+e);}
std::vector<std::uint8_t> Info(std::string_view mime,std::string_view name){if(mime.size()>255||name.size()>255)throw std::runtime_error("module descriptor too long");std::vector<std::uint8_t>b{0x01,static_cast<std::uint8_t>(mime.size())};b.insert(b.end(),mime.begin(),mime.end());b.push_back(0x02);b.push_back(static_cast<std::uint8_t>(name.size()));b.insert(b.end(),name.begin(),name.end());if(b.size()>255)throw std::runtime_error("module_info exceeds 255 bytes");return b;}
std::vector<std::uint8_t> Section(std::uint8_t table,std::uint16_t ext,std::uint8_t version,std::uint8_t sec,std::uint8_t last,std::span<const std::uint8_t>payload){const auto len=5+payload.size()+4;if(len>4093)throw std::runtime_error("DSM-CC section exceeds 4093 bytes");std::vector<std::uint8_t>b{table,static_cast<std::uint8_t>(0xb0|(len>>8)),static_cast<std::uint8_t>(len)};U16(b,ext);b.push_back(static_cast<std::uint8_t>(0xc1|((version&31)<<1)));b.push_back(sec);b.push_back(last);b.insert(b.end(),payload.begin(),payload.end());Crc(b);return b;}
std::vector<std::uint8_t> Header(std::uint16_t id,std::uint32_t transaction,std::size_t body){if(body>0xffff)throw std::runtime_error("DSM-CC message too large");std::vector<std::uint8_t>b{0x11,0x03};U16(b,id);U32(b,transaction);b.push_back(0xff);b.push_back(0);U16(b,static_cast<std::uint16_t>(body));return b;}
void ValidateImage(const std::filesystem::path&p,std::span<const std::uint8_t>d){const auto e=Lower(p.extension().string());if(e==".png"&&(d.size()<8||!std::equal(d.begin(),d.begin()+8,std::array<std::uint8_t,8>{137,80,78,71,13,10,26,10}.begin())))throw std::runtime_error("invalid PNG resource");if((e==".jpg"||e==".jpeg")&&(d.size()<4||d[0]!=0xff||d[1]!=0xd8||d[d.size()-2]!=0xff||d.back()!=0xd9))throw std::runtime_error("invalid JPEG resource");}
}
std::vector<std::filesystem::path>BmlResourceScanner::Scan(const DataBroadcastSettings&s){if(s.root.empty()||!std::filesystem::is_directory(s.root))throw std::runtime_error("data broadcast root is not a directory");const auto root=std::filesystem::weakly_canonical(s.root);std::vector<std::filesystem::path>v;for(const auto&e:std::filesystem::recursive_directory_iterator(root)){if(!e.is_regular_file())continue;const auto real=std::filesystem::weakly_canonical(e.path());auto rel=std::filesystem::relative(real,root);if(rel.empty()||rel.is_absolute()||rel.generic_string().starts_with(".."))throw std::runtime_error("data resource escapes root");(void)Mime(rel);v.push_back(rel);}std::sort(v.begin(),v.end(),[](const auto&a,const auto&b){return a.generic_string()<b.generic_string();});if(v.size()>s.max_modules)throw std::runtime_error("too many carousel modules");const auto entry=std::filesystem::path(s.entry).lexically_normal();if(entry.is_absolute()||entry.generic_string().starts_with("..")||std::find(v.begin(),v.end(),entry)==v.end())throw std::runtime_error("data broadcast entry is missing or unsafe");return v;}
void BmlResourceScanner::ValidateBml(std::span<const std::uint8_t>d,std::string_view name){const std::string s(reinterpret_cast<const char*>(d.data()),d.size());if(s.find("<?xml")==std::string::npos||s.find("version=\"1.0\"")==std::string::npos)throw std::runtime_error(std::string(name)+": XML 1.0 declaration required");if(s.find("encoding=\"UTF-8\"")==std::string::npos&&s.find("encoding='UTF-8'")==std::string::npos)throw std::runtime_error(std::string(name)+": Milestone 7 supports UTF-8 BML");const auto open=s.find("<bml");const auto close=s.rfind("</bml>");if(open==std::string::npos||close==std::string::npos||close<open)throw std::runtime_error(std::string(name)+": BML root is malformed");int depth=0;for(std::size_t p=0;(p=s.find('<',p))!=std::string::npos;){if(s.compare(p,4,"<!--")==0){const auto q=s.find("-->",p+4);if(q==std::string::npos)throw std::runtime_error("unterminated XML comment");p=q+3;continue;}const auto q=s.find('>',p+1);if(q==std::string::npos)throw std::runtime_error("unterminated XML tag");if(s[p+1]!='?'&&s[p+1]!='!'&&s[p+1]!='/'&&s[q-1]!='/')++depth;else if(s[p+1]=='/'&&--depth<0)throw std::runtime_error("unbalanced XML tags");p=q+1;}if(depth!=0)throw std::runtime_error("unbalanced XML tags");}
DataCarousel CarouselModuleBuilder::Build(const DataBroadcastSettings&s){if(s.block_size<256||s.block_size>4066)throw std::runtime_error("block_size must be 256..4066");if((s.download_id>>28)!=(s.data_event_id&15))throw std::runtime_error("download_id high nibble must match data_event_id");DataCarousel c{s.download_id,s.block_size,{"A-profile","1.0",s.entry,{}}};const auto paths=BmlResourceScanner::Scan(s);std::size_t total=0;std::set<std::uint16_t>ids;for(const auto&rel:paths){CarouselModule m;m.path=rel.generic_string();m.data=Read(s.root/rel);if(m.data.size()>s.max_module_bytes)throw std::runtime_error("carousel module exceeds max_module_bytes");total+=m.data.size();if(total>s.max_total_bytes)throw std::runtime_error("carousel exceeds max_total_bytes");m.mime=Mime(rel);ValidateImage(rel,m.data);if(Lower(rel.extension().string())==".bml")BmlResourceScanner::ValidateBml(m.data,m.path);if(m.path==s.entry)m.id=0;else{m.id=static_cast<std::uint16_t>((Hash(m.path)&0xfffe)+1);while(!ids.insert(m.id).second||m.id==0)m.id=static_cast<std::uint16_t>(m.id+1);}ids.insert(m.id);m.version=static_cast<std::uint8_t>(Hash(m.data));m.module_info=Info(m.mime,m.path);c.application.modules.push_back(std::move(m));}std::stable_sort(c.application.modules.begin(),c.application.modules.end(),[](const auto&a,const auto&b){return a.id==0||(b.id!=0&&a.path<b.path);});return c;}
std::vector<std::uint8_t>DiiGenerator::Generate(const DataCarousel&c,std::uint32_t tid){std::vector<std::uint8_t>body;U32(body,c.download_id);U16(body,c.block_size);body.push_back(0);body.push_back(0);U32(body,0);U32(body,5000000);U16(body,2);U16(body,0);U16(body,static_cast<std::uint16_t>(c.application.modules.size()));for(const auto&m:c.application.modules){U16(body,m.id);U32(body,static_cast<std::uint32_t>(m.data.size()));body.push_back(m.version);body.push_back(static_cast<std::uint8_t>(m.module_info.size()));body.insert(body.end(),m.module_info.begin(),m.module_info.end());}U16(body,0);auto msg=Header(kDsmccMessageIdDii,tid,body.size());msg.insert(msg.end(),body.begin(),body.end());return Section(kTableIdDii,static_cast<std::uint16_t>(tid),0,0,0,msg);}
std::vector<std::vector<std::uint8_t>>DdbGenerator::Generate(const DataCarousel&c){std::vector<std::vector<std::uint8_t>>out;for(const auto&m:c.application.modules){const auto count=std::max<std::size_t>(1,(m.data.size()+c.block_size-1)/c.block_size);if(count>256)throw std::runtime_error("module needs more than 256 DDB sections");for(std::size_t n=0;n<count;++n){const auto begin=std::min(n*c.block_size,m.data.size()),end=std::min(begin+c.block_size,m.data.size());std::vector<std::uint8_t>body;U16(body,m.id);body.push_back(m.version);body.push_back(0xff);U16(body,static_cast<std::uint16_t>(n));body.insert(body.end(),m.data.begin()+begin,m.data.begin()+end);auto msg=Header(kDsmccMessageIdDdb,c.download_id,body.size());msg.insert(msg.end(),body.begin(),body.end());out.push_back(Section(kTableIdDdb,m.id,m.version,static_cast<std::uint8_t>(n),static_cast<std::uint8_t>(count-1),msg));}}return out;}
std::vector<std::vector<std::uint8_t>>DsmccGenerator::GenerateAll(const DataCarousel&c){auto v=DdbGenerator::Generate(c);v.insert(v.begin(),DiiGenerator::Generate(c));return v;}
std::vector<std::uint8_t>DataBroadcastDescriptorWriter::PmtDescriptors(std::uint8_t e){return {0x52,0x01,kBmlComponentTag,0xfd,0x03,0x00,0x0c,static_cast<std::uint8_t>(((e&15)<<4)|0x07)};}
CarouselScheduler::CarouselScheduler(const DataBroadcastSettings&s):settings_(s){}
std::vector<std::vector<std::uint8_t>>CarouselScheduler::Due(const DataCarousel&c,std::chrono::steady_clock::time_point now){std::vector<std::vector<std::uint8_t>>out;if(next_dii_.time_since_epoch().count()==0||now>=next_dii_){out.push_back(DiiGenerator::Generate(c));next_dii_=now+settings_.dii_interval;}auto blocks=DdbGenerator::Generate(c);if(!blocks.empty()&&(next_block_.time_since_epoch().count()==0||now>=next_block_)){out.push_back(blocks[block_++]);const auto bytes=blocks[block_-1].size()+4;const auto ms=std::max<std::int64_t>(1,bytes*8*1000/(settings_.max_bitrate_kbps*1000));next_block_=now+std::chrono::milliseconds(ms);if(block_==blocks.size()){block_=0;next_block_=std::max(next_block_,now+settings_.carousel_cycle);}}return out;}
DataBroadcastManager::DataBroadcastManager(DataBroadcastSettings s):settings_(std::move(s)),scheduler_(settings_){if(settings_.enabled)carousel_=CarouselModuleBuilder::Build(settings_);}
std::vector<std::vector<std::uint8_t>>DataBroadcastManager::Due(std::chrono::steady_clock::time_point now){return carousel_?scheduler_.Due(*carousel_,now):std::vector<std::vector<std::uint8_t>>{};}
}
